#!/usr/bin/env bash
# Writes Casks/logn.rb into a checkout of Stringsaeed/homebrew-tap.
# Usage: update-cask.sh <version> <dmg-sha256> <tap-dir>
set -euo pipefail
VERSION=${1:-} SHA=${2:-} TAP=${3:-}
[[ $VERSION =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "error: version must be X.Y.Z" >&2; exit 1; }
[[ $SHA =~ ^[0-9a-fA-F]{64}$ ]] || { echo "error: sha256 must be 64 hex characters" >&2; exit 1; }
[[ -n $TAP ]] || { echo "error: tap dir is required" >&2; exit 1; }
SHA=$(printf '%s' "$SHA" | tr '[:upper:]' '[:lower:]')
mkdir -p "$TAP/Casks"
cat > "$TAP/Casks/logn.rb" <<CASK
# Generated by Logn's release workflow (scripts/release/update-cask.sh). Don't edit by hand.
cask "logn" do
  version "$VERSION"
  sha256 "$SHA"

  url "https://github.com/Stringsaeed/o-log-n/releases/download/v#{version}/Logn-#{version}.dmg"
  name "Logn"
  desc "Compress any file from the menu bar"
  homepage "https://ologn.app/"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on arch: :arm64
  depends_on macos: :tahoe

  app "Logn.app"

  uninstall quit: "app.ologn.mac"

  zap trash: [
    "~/Library/Application Support/Logn",
    "~/Library/Caches/app.ologn.mac",
    "~/Library/Preferences/app.ologn.mac.plist",
    "~/Library/Saved Application State/app.ologn.mac.savedState",
  ]
end
CASK
echo "wrote $TAP/Casks/logn.rb ($VERSION)"
